<script lang="ts">import{DirectPrintRoute}from'../print/direct.js';import{WebBluetoothTransport,WebSerialTransport,WebUsbTransport}from'../print/browser-transports.js';import{JobJournal}from'../jobs.js';import type{EditorDatabase}from'../persistence/database.js';import type{LabelDocument}from'../model.js';import type{PrinterDefinition,PrinterSdk,PrinterStatus,PrintRoute}from'../print/types.js';export let sdk:PrinterSdk;export let document:LabelDocument;export let printer:PrinterDefinition|undefined;export let database:EditorDatabase;export let onRoute:(route:PrintRoute)=>void=()=>{};export let onMedia:(media:{width:number;height:number;shape:'rectangle'|'round'|'continuous'})=>void=()=>{};let route:'bluetooth'|'spp'|'usb'='bluetooth';let service='0000ff00-0000-1000-8000-00805f9b34fb';let write='0000ff02-0000-1000-8000-00805f9b34fb';let notify='0000ff03-0000-1000-8000-00805f9b34fb';let vendorId='0x04f9';let productId='0x20a8';let status='';let active:DirectPrintRoute|undefined;let cancellation:AbortController|undefined;let printerStatus:PrinterStatus|undefined;let querying=false;
function configure(){const journal=new JobJournal(database);if(route==='bluetooth')active=new DirectPrintRoute(sdk,async()=>new WebBluetoothTransport({service,writeCharacteristic:write,notifyCharacteristic:notify}),'bluetooth',()=>!!(navigator as Navigator&{bluetooth?:unknown}).bluetooth,journal);else if(route==='spp')active=new DirectPrintRoute(sdk,async()=>new WebSerialTransport({physicalWriteLimit:512,unfiltered:true}),'serial',()=>!!(navigator as Navigator&{serial?:unknown}).serial,journal);else active=new DirectPrintRoute(sdk,async()=>new WebUsbTransport({filters:[{vendorId:Number(vendorId),productId:Number(productId)}],interfaceNumber:0}),'usb',()=>!!(navigator as Navigator&{usb?:unknown}).usb,journal);onRoute(active);status=`${active.label} selected for direct, batch, and La Poste printing.`}
async function print(){if(!printer){status='Select a printer model first.';return}if(!active)configure();cancellation=new AbortController();status='Choose a device in the browser prompt…';const result=await active!.print({document,printer,copies:1,signal:cancellation.signal,onProgress:p=>status=`${p.phase}: ${p.bytesSent}/${p.totalBytes} bytes`});cancellation=undefined;status=result.outcome==='completed'?'Direct print completed.':`${result.outcome}: ${result.error??'Do not retry until the physical printer is checked.'}`;if(result.outcome==='failed'||result.outcome==='cancelled-before-send')active=undefined}
function applyMedia(){if(!printerStatus)return;const found=printerStatus.media;const width=found?.widthMm??printerStatus.mediaWidthMm;if(width===undefined){status='The printer did not report a media size.';return}
  const continuous=found?found.shape==='continuous':printerStatus.mediaType==='continuous';
  const height=found&&found.heightMm?found.heightMm:printerStatus.mediaLengthMm||0;
  onMedia({width,height:continuous||!height?document.media.height:height,shape:found?.shape==='round'?'round':continuous?'continuous':'rectangle'});
  status=`Label set to the media in the printer${found?`: ${found.name}`:''}.`}
async function readStatus(){if(!printer){status='Select a printer model first.';return}if(!active)configure();querying=true;printerStatus=undefined;status='Choose a device in the browser prompt…';try{printerStatus=await active!.queryStatus(printer);status=`Read status from ${printer.displayName}.`}catch(error){status=error instanceof Error?error.message:String(error)}finally{querying=false}}
</script>
<section><h2>Direct browser print</h2><label>Route<select bind:value={route} on:change={()=>active=undefined}><option value="bluetooth">Web Bluetooth (BLE)</option><option value="spp">Bluetooth SPP (Web Serial)</option><option value="usb">WebUSB</option></select></label>{#if route==='bluetooth'}<details><summary>Bluetooth definition</summary><label>Service UUID<input bind:value={service}></label><label>Write UUID<input bind:value={write}></label><label>Notify UUID<input bind:value={notify}></label></details>{:else if route==='spp'}<p class="hint">Pair the printer first. On macOS choose the mapped QL serial port (cu.QL-1110NWB…), not the direct Bluetooth entry.</p>{:else}<label>USB vendor ID<input bind:value={vendorId}></label><label>USB product ID<input bind:value={productId}></label>{/if}<button on:click={configure}>Use for all print workflows</button><button on:click={print} disabled={!!cancellation}>Choose device & print current label</button><button on:click={readStatus} disabled={querying||!!cancellation}>Read printer status</button>{#if printerStatus&&(printerStatus.media||printerStatus.mediaWidthMm!==undefined)}<button on:click={applyMedia}>Use this media for the label</button>{/if}{#if cancellation}<button on:click={()=>cancellation?.abort()}>Cancel current job</button>{/if}<p aria-live="polite">{status}</p>{#if printerStatus}<dl class="printer-status">{#if printerStatus.media}<dt>Media</dt><dd>{printerStatus.media.name}</dd>{/if}{#if printerStatus.mediaWidthMm!==undefined}<dt>Media width</dt><dd>{printerStatus.mediaWidthMm} mm</dd><dt>Media length</dt><dd>{printerStatus.mediaLengthMm?`${printerStatus.mediaLengthMm} mm`:'continuous'}</dd><dt>Media type</dt><dd>{printerStatus.mediaType ?? '—'}</dd><dt>Phase</dt><dd>{printerStatus.phase ?? '—'}</dd>{/if}{#if printerStatus.battery!==undefined}<dt>Battery</dt><dd>{printerStatus.battery}</dd>{/if}{#if printerStatus.paper}<dt>Paper</dt><dd>{printerStatus.paper}</dd>{/if}{#if printerStatus.cover}<dt>Cover</dt><dd>{printerStatus.cover}</dd>{/if}{#if printerStatus.label}<dt>Label</dt><dd>{printerStatus.label}</dd>{/if}{#if printerStatus.heating}<dt>Print head</dt><dd>{printerStatus.heating}</dd>{/if}{#if printerStatus.firmware}<dt>Firmware</dt><dd>{printerStatus.firmware}</dd>{/if}{#if printerStatus.serial}<dt>Serial</dt><dd>{printerStatus.serial}</dd>{/if}<dt>Errors</dt><dd class:fault={!!printerStatus.errors.length}>{printerStatus.errors.length?printerStatus.errors.join(', '):'none'}</dd></dl>{/if}</section><style>section{padding:.7rem .75rem;border-top:1px solid var(--mble-border,#e5dfd5)}h2{margin:0 0 .5rem;color:var(--mble-text-muted,#59635e);font-size:.75rem;font-weight:600}label{display:flex;flex-direction:column;font-size:.75rem}.hint{font-size:.75rem;color:var(--mble-text-muted,#59635e)}.printer-status{display:grid;grid-template-columns:auto 1fr;gap:.15rem .6rem;margin:.4rem 0 0;font-size:.75rem}.printer-status dt{color:var(--mble-text-muted,#59635e)}.printer-status dd{margin:0}.fault{color:var(--mble-danger,#a21)}</style>
